    {
      "id": "follow-3",
      "kind": "prepare_information",
      "text": {
        "en": "Record the rejection reason, preserve the original recommendation, and note which facts remain unverified; do not overwrite or delete the human view.",
        "zh": "记录否决原因，保留原建议，并注明哪些事实仍未核实；不得覆盖或删除人工意见。"
      },
      "evidenceIds": [
        "EVT005",
        "RULE006"
      ],
      "ruleIds": [
        "RULE006"
      ]
    },
    {
      "id": "follow-4",
      "kind": "prepare_draft",
      "text": {
        "en": "Prepare passenger-facing wording using only public facts, uncertainty, and official-update guidance; do not include internal speculation or unconfirmed delay or cancellation claims.",
        "zh": "准备面向旅客的措辞，仅使用公开事实、不确定性说明和官方更新指引；不得包含内部推测或未经确认的延误、取消说法。"
      },
      "evidenceIds": [
