  "escalationConditions": [
    {
      "en": "If official status confirms a safety-related restriction, delay, or cancellation, stop action conclusions and refer to the operations lead.",
      "zh": "若正式状态确认存在安全相关限制、延误或取消，停止行动结论并提交运营负责人。"
    },
    {
      "en": "If source reliability cannot be judged, stop action conclusions and refer to the operations lead with the information gaps listed.",
      "zh": "若无法判断来源可靠性，停止行动结论，并连同所列信息缺口提交运营负责人。"
    },
    {
      "en": "If the consolidated confirmation identifies unresolved de-icing, ground-handling, wind-limit, or staffing constraints, escalate for human review.",
      "zh": "若综合确认发现除冰、地面保障、风速限制或人员配置存在未解决约束，升级提交人工复核。"
    },
    {
      "en": "If a second independent current report indicates expanding impact, escalate and state the triggering evidence.",
      "zh": "若第二份独立当前报告显示影响范围可能扩大，升级并说明触发证据。"
    },
    {
      "en": "If a cancellation, release, dispatch, maintenance, or compensation decision is requested, refer it to the accountable professional rather than making or recommending the decision.",
      "zh": "若要求作出取消、放行、调度、维修或赔付决定，提交相应专业负责人，而不是作出或建议该决定。"
    }
  ],
  "humanDecisions": [
    {
      "en": "Approve or amend the consolidated information request before any sending.",
      "zh": "在任何发送前批准或修改综合信息请求。"
    },
